#!/usr/bin/env node
/**
 * Build plugin/bridge/remote-control-bridge.cjs from bridge/src.
 *
 * That 260KB file is committed, and it is what users actually run: the plugin
 * spawns it directly (plugin/bridge-runner.js -> BUNDLED_BIN) so a git or npm
 * install works with no build step. Until this script existed nothing in the
 * repo produced it — the bundle was regenerated by hand, off the record, so a
 * change to bridge/src that was never re-bundled would ship to every user as
 * the OLD behaviour with no signal anywhere. CI now rebuilds it and fails on
 * a mismatch (.github/workflows/ci.yml), which only works because this file
 * is the single, exact definition of how it is built.
 *
 * Run it from the bridge package: `npm run bundle` in bridge/.
 */
import { createRequire } from 'node:module'
import { chmodSync, mkdirSync, openSync, readSync, closeSync, statSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { pathToFileURL } from 'node:url'

const REPO_ROOT = dirname(import.meta.dirname)
const BRIDGE_DIR = join(REPO_ROOT, 'bridge')
const ENTRY = 'src/index.ts'
const OUTFILE = join(REPO_ROOT, 'plugin', 'bridge', 'remote-control-bridge.cjs')

// esbuild is a devDependency of bridge/, not of the repo root, and this script
// lives outside that package — so resolve it against bridge/package.json
// rather than against this file's own directory, where Node would find nothing.
const require = createRequire(pathToFileURL(join(BRIDGE_DIR, 'package.json')))
const esbuild = require('esbuild')

// The committed bundle's first line. The file is mode 755 and may be executed
// directly, so losing the shebang would turn it into a shell script; assert it
// rather than prepending a banner, because esbuild already hoists the hashbang
// from the entry point (bridge/src/index.ts) and a banner would emit a second,
// non-leading '#!' line that Node rejects.
const SHEBANG = '#!/usr/bin/env node'

mkdirSync(dirname(OUTFILE), { recursive: true })

const result = await esbuild.build({
  // Pinning the working directory to bridge/ keeps the build byte-reproducible
  // across checkouts: esbuild annotates every bundled module with its path
  // relative to this directory ('// src/index.ts', '// node_modules/ws/...'),
  // so a build run from anywhere else would rewrite ~35 comment lines and make
  // CI's drift check fail on nothing but the clone location.
  absWorkingDir: BRIDGE_DIR,
  entryPoints: [ENTRY],
  outfile: OUTFILE,
  bundle: true,
  platform: 'node',
  format: 'cjs',
  // Matches the `engines.node: >=22` both packages declare.
  target: 'node22',
  logLevel: 'info',
})

// Expected, and load-bearing: index.ts uses import.meta.url to decide whether
// it was invoked as a CLI, which cjs cannot provide — hence the argv[1]
// filename fallback in that same check. The warning stays UNSILENCED so a
// future import.meta use that has no such fallback is still visible here.
if (result.warnings.some((w) => w.id === 'empty-import-meta')) {
  console.log(
    "note: the 'empty-import-meta' warning above is expected — the CLI entry check falls back to process.argv[1].",
  )
}

// Read only the first line back: the bundle is 260KB and there is no reason to
// pull all of it into memory to check one line.
const fd = openSync(OUTFILE, 'r')
const head = Buffer.alloc(SHEBANG.length + 1)
readSync(fd, head, 0, head.length, 0)
closeSync(fd)
if (head.subarray(0, SHEBANG.length).toString('utf8') !== SHEBANG) {
  throw new Error(
    `${OUTFILE} does not start with ${SHEBANG} — bridge/src/index.ts lost its shebang, and the committed bundle is executable`,
  )
}

// esbuild sets the executable bit itself for hashbang output; set it anyway so
// the committed mode (100755) never depends on that behaviour staying put.
chmodSync(OUTFILE, 0o755)

console.log(`wrote ${OUTFILE} (${statSync(OUTFILE).size} bytes)`)
